cssFirst.themeBlock:
@theme {
  --color-lime: #CCFF00;
  --color-pink: #FF2D78;
  --color-cyan: #00F5FF;
  --color-violet: #B44FFF;
  --color-bg: #060608;
  --color-surface: #0d0d12;
  --color-surface-2: #14141c;
  --color-ink: #F0F0F8;
  --color-muted: #7a7a90;
  --font-display: "Syne", "Sarabun", system-ui, sans-serif;
  --font-sans: "DM Sans", "Sarabun", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --shadow-brutal: 6px 6px 0 rgb(0 0 0 / .8);
  --ease-spring: cubic-bezier(.34, 1.45, .64, 1);
  --breakpoint-3xl: 1920px;
}
